<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch,markRaw} from 'vue';
import ColorFilterControls from './ColorFilterControls.vue';
import LiquifyDialog from './LiquifyDialog.vue';
import {defaultFilterNode,validateFilterNode,capturedCoverage,EDITABLE_FILTERS} from '../../../packages/comp-bridge/editable-filters.mjs';
import {parityMessages}from'./parity-labels';
import {localizedMessages}from'../../../packages/locales';
import type{Language,ViewerProject,LayerRow,OpenResult}from'./types';
const props=defineProps<{language:Language;project:ViewerProject;layer:LayerRow;initialLiquify?:boolean;commit:(op:Record<string,unknown>,owner:{id:string;revision:string})=>Promise<OpenResult>}>();
const emit=defineEmits(['close']);
const owner={id:props.project.id,revision:props.project.revision},t=computed(()=>parityMessages[props.language]),nodes=ref<any[]>([]),selected=ref(0),kind=ref('Gaussian Blur'),busy=ref(true),applying=ref(false),error=ref(''),preview=ref<HTMLCanvasElement>(),beforeCanvas=ref<HTMLCanvasElement>(),stale=ref(true),liquifySource=ref<any>(),liquifyNode=ref<any>();
let source:any,worker:Worker|undefined,epoch=0,loaded=ref(false),liquifyIndex=-1,closed=false;
const copyRequired=!!(props.layer.text||props.layer.shape||props.layer.fill),createsCopy=ref(!!props.initialLiquify||copyRequired);
const current=computed(()=>nodes.value[selected.value]);
const colorControls=computed(()=>current.value?{kind:current.value.kind,halftone:current.value.halftone,colorLUT:current.value.lut}:{});
const valid=computed(()=>loaded.value&&nodes.value.every(node=>{try{validateFilterNode(node,source.width,source.height);return true;}catch{return false;}}));
const nodeName=(node:any)=>t.value.stackKinds[EDITABLE_FILTERS.indexOf(node.kind)]??node.kind;
function draw(canvas:HTMLCanvasElement|undefined,image:any){if(!canvas)return;canvas.width=image.width;canvas.height=image.height;canvas.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.width,image.height),0,0);}
function plain(){return JSON.parse(JSON.stringify(nodes.value));}
async function load(){try{
  const record=props.layer.editableFilters,key=record?`edits/${record.sourceFile}`:`images/${props.layer.imageFile}`,response=await fetch(props.project.urls[key]);if(!response.ok)throw new Error('asset');const bitmap=await createImageBitmap(await response.blob());
  if(!preview.value){bitmap.close();return;}const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const context=canvas.getContext('2d')!;context.drawImage(bitmap,0,0);bitmap.close();const image=context.getImageData(0,0,canvas.width,canvas.height);source={width:image.width,height:image.height,data:image.data};canvas.width=canvas.height=1;
  if(record)nodes.value=await Promise.all(record.nodeFiles.map(async file=>{const response=await fetch(props.project.urls[`edits/${file}`]);if(!response.ok)throw new Error('asset');const node=await response.json();validateFilterNode(node,source.width,source.height);if(node.lut.table)node.lut.table=markRaw(node.lut.table);return node;}));
  if(closed)return;loaded.value=true;draw(beforeCanvas.value,source);busy.value=false;
  if(props.initialLiquify)await add('Advanced Liquify');else await refresh();
}catch{error.value=t.value.failed;busy.value=false;}}
function evaluate(count=nodes.value.length):Promise<any>{const own=++epoch;worker?.terminate();return new Promise((resolve,reject)=>{const active=worker=new Worker(new URL('./filter-stack-worker.ts',import.meta.url),{type:'module'});active.onmessage=event=>{active.terminate();if(own!==epoch)return;worker=undefined;if(event.data.error)reject(new Error(event.data.error));else resolve(event.data.image);};active.onerror=()=>{active.terminate();if(own===epoch){worker=undefined;reject(new Error('invalid'));}};active.postMessage({source,nodes:plain().slice(0,count)});});}
async function refresh(){if(!loaded.value||!valid.value)return;busy.value=true;error.value='';try{draw(preview.value,await evaluate());stale.value=false;}catch{error.value=t.value.failed;}finally{busy.value=false;}}
async function add(value=kind.value){if(!loaded.value||nodes.value.length>=32)return;if(value==='Advanced Liquify'){liquifyIndex=nodes.value.length;busy.value=true;try{liquifySource.value=markRaw(await evaluate());liquifyNode.value=undefined;}catch{error.value=t.value.failed;}finally{busy.value=false;}return;}const node:any=defaultFilterNode(value),coverage=capturedCoverage(props.project.selection,props.layer.transform,source.width,source.height);if(coverage!==undefined)node.coverage=coverage;nodes.value.push(node);selected.value=nodes.value.length-1;}
async function editLiquify(){liquifyIndex=selected.value;busy.value=true;try{liquifySource.value=markRaw(await evaluate(liquifyIndex));liquifyNode.value=JSON.parse(JSON.stringify(current.value.liquify));}catch{error.value=t.value.failed;}finally{busy.value=false;}}
function acceptLiquify(saved:any){if(liquifyIndex<nodes.value.length)nodes.value[liquifyIndex].liquify=saved;else{const node:any=defaultFilterNode('Advanced Liquify');node.liquify=saved;const coverage=capturedCoverage(props.project.selection,props.layer.transform,source.width,source.height);if(coverage!==undefined)node.coverage=coverage;nodes.value.push(node);}selected.value=liquifyIndex;liquifySource.value=undefined;}
function move(delta:number){const index=selected.value,next=index+delta;if(next<0||next>=nodes.value.length)return;[nodes.value[index],nodes.value[next]]=[nodes.value[next],nodes.value[index]];selected.value=next;}
function remove(){nodes.value.splice(selected.value,1);selected.value=Math.max(0,selected.value-1);}
async function apply(){if(!valid.value)return;applying.value=true;error.value='';try{const result=await props.commit({kind:'filterStack',id:props.layer.id,nodes:plain(),copy:createsCopy.value},owner);if(result.project)emit('close');else if(result.error)error.value=(localizedMessages(props.language,'windows').errors as Record<string,string>)[result.error]??t.value.failed;}catch{error.value=t.value.failed;}finally{applying.value=false;}}
watch(nodes,()=>{stale.value=true;error.value='';},{deep:true});
onMounted(load);onUnmounted(()=>{closed=true;epoch++;worker?.terminate();});
</script>
<template><div class="modal-shade" @click.self="!applying&&emit('close')"><section role="dialog" aria-modal="true" :aria-label="t.filterStack" class="dialog filter-stack-dialog" @keydown.esc.stop.prevent="!applying&&!liquifySource&&emit('close')"><h2>{{t.filterStack}}</h2><p>{{t.stackTip}}</p><p v-if="error" role="alert">{{error}}</p><fieldset :disabled="busy||applying||!!liquifySource"><div class="button-row"><select v-model="kind" data-testid="stack-add-kind"><option v-for="(id,index) in EDITABLE_FILTERS" :key="id" :value="id">{{t.stackKinds[index]}}</option></select><button data-testid="stack-add" :disabled="nodes.length>=32" @click="add()">{{t.addFilter}}</button></div><div class="stack-layout"><div><ol class="stack-nodes"><li v-for="(node,index) in nodes" :key="node.id"><input v-model="node.enabled" :aria-label="t.enabled+' '+(index+1)" type="checkbox"><button :aria-pressed="selected===index" @click="selected=index">{{index+1}}. {{nodeName(node)}}</button></li></ol><div class="button-row"><button :disabled="!current||selected===0" @click="move(-1)">↑</button><button :disabled="!current||selected===nodes.length-1" @click="move(1)">↓</button><button :disabled="!current" @click="remove()">{{t.remove}}</button></div></div><div v-if="current" class="stack-settings"><label>{{t.opacity}}<input v-model.number="current.opacity" type="number" min="0" max="1" step=".01"></label><label v-if="current.kind==='Gaussian Blur'">{{t.radius}}<input v-model.number="current.radius" data-testid="stack-radius" type="number" min=".1" max="250" step=".1"></label><template v-if="current.kind==='Motion Blur'"><label>{{t.angle}}<input v-model.number="current.angle" type="number" min="-90" max="90"></label><label>{{t.distance}}<input v-model.number="current.distance" type="number" min="1" max="2000"></label></template><template v-if="current.kind==='Add Noise'"><label>{{t.amount}}<input v-model.number="current.amount" type="number" min=".1" max="400" step=".1"></label><label>{{t.seed}}<input v-model.number="current.seed" type="number" min="0" max="4294967295"></label><label><input v-model="current.gaussian" type="checkbox">{{t.gaussian}}</label><label><input v-model="current.monochromatic" type="checkbox">{{t.monochromatic}}</label></template><ColorFilterControls :value="colorControls" :language="language"/><button v-if="current.kind==='Advanced Liquify'" data-testid="edit-saved-liquify" @click="editLiquify()">{{t.editLiquify}}</button><button v-if="current.coverage" @click="current.coverage=null">{{t.clearFilterMask}}</button></div></div><div class="stack-previews"><figure><figcaption>{{t.before}}</figcaption><canvas ref="beforeCanvas"></canvas></figure><figure><figcaption>{{t.after}}</figcaption><canvas ref="preview" data-testid="stack-preview"></canvas></figure></div><p v-if="stale">{{t.previewStale}}</p><button :disabled="!valid" data-testid="stack-preview-refresh" @click="refresh()">{{t.refreshPreview}}</button></fieldset><label><input v-model="createsCopy" type="checkbox" :disabled="applying||copyRequired">{{t.createCopy}}</label><p v-if="copyRequired">{{t.copyRequired}}</p><div class="button-row dialog-actions"><button :disabled="applying" @click="emit('close')">{{t.cancel}}</button><button class="primary" data-testid="apply-filter-stack" :disabled="busy||applying||!valid||!!liquifySource" @click="apply()">{{applying?t.loading:t.apply}}</button></div><LiquifyDialog v-if="liquifySource" :language="language" :source="liquifySource" :saved="liquifyNode" @close="liquifySource=undefined" @apply="acceptLiquify"/></section></div></template>
<style scoped>.filter-stack-dialog{width:min(1040px,96vw);max-height:94vh;overflow:auto}.filter-stack-dialog>fieldset{border:0;padding:0}.stack-layout{display:grid;grid-template-columns:minmax(180px,1fr) 2fr;gap:16px;margin:12px 0}.stack-nodes{list-style:none;padding:0;max-height:200px;overflow:auto}.stack-nodes li{display:flex;align-items:center;gap:6px;margin-bottom:4px}.stack-nodes button[aria-pressed=true]{background:var(--accent);color:#10291e}.stack-settings{max-height:260px;overflow:auto}.stack-settings>label{display:flex;gap:8px;margin:6px}.stack-previews{display:flex;gap:16px}.stack-previews figure{width:50%;margin:0}.stack-previews canvas{max-width:100%;max-height:240px;object-fit:contain;background:repeating-conic-gradient(#666 0 25%,#888 0 50%) 0/16px 16px}</style>
